using System.Text.Json;
using System.Text.Json.Nodes;
using CadModeling.Ir;
using CadModeling.Core;

var draft = CompactModelInputs.Decode<GenericModelDraft>(SourceWorkflowInputs.Prepare(JsonNode.Parse(File.ReadAllText(args[0]))!).Input);
var context = draft.DrawingContext!;
var orientation = context.ModelOrientation!;
var frames = draft.Operations.Select(o => (o.Id, o.Frame)).ToArray();
var results = new List<string>();
void Check(bool ok,string name) { if(!ok)throw new Exception(name);results.Add(name);Console.WriteLine("PASS "+name); }
IReadOnlyList<ModelingDiagnostic> Validate(DrawingPlanContext c, (string Id,SketchFrame? Frame)[]? f=null) => DrawingModelOrientationValidation.Validate(c,f??frames);
bool Has(DrawingPlanContext c,string code,(string Id,SketchFrame? Frame)[]? f=null) => Validate(c,f).Any(d=>d.Code==code);
Check(Validate(context).Count==0,"corrected signed directions pass");
Check(Has(context with{ModelOrientation=null},"SOURCE_MODEL_ORIENTATION_REQUIRED"),"new revision requires source basis");
Check(Validate(context with{WorkflowRevision=SourceWorkflow.FourStageRevision,ModelOrientation=null}).Count==0,"explicit legacy contract remains legacy");
Check(Has(context with{ModelOrientation=orientation with{DirectionBindings=[]}},"SOURCE_MODEL_DIRECTION_REQUIRED"),"empty bindings cannot bypass required direction proof");
Check(Has(context with{ModelOrientation=orientation with{DirectionBindings=orientation.DirectionBindings.Take(3).ToArray()}},"SOURCE_MODEL_DIRECTION_REQUIRED"),"missing one hole binding fails");
Check(Has(context with{ModelOrientation=orientation with{DirectionBindings=orientation.DirectionBindings.Append(orientation.DirectionBindings[0]).ToArray()}},"SOURCE_MODEL_DIRECTION_BINDING"),"duplicate binding rejected");
Check(Has(context with{ModelOrientation=orientation with{FrontUp=orientation.FrontRight}},"SOURCE_MODEL_ORIENTATION_BASIS"),"nonorthogonal basis rejected");
Check(Has(context with{ModelOrientation=orientation with{FrontRight=new(2,0,0)}},"SOURCE_MODEL_ORIENTATION_BASIS"),"nonunit basis rejected");
Check(Has(context with{ModelOrientation=orientation with{State=DrawingReviewState.Unresolved}},"SOURCE_MODEL_ORIENTATION_BASIS"),"unreviewed basis rejected");
var mirror = frames.Select(f => (f.Id,f.Frame is null?null:f.Frame with{XDirection=new(f.Frame.XDirection.X,f.Frame.XDirection.Y,-f.Frame.XDirection.Z)})).ToArray();
Check(Has(context,"SOURCE_MODEL_DIRECTION_MISMATCH",mirror),"front-back mirror rejected");
var reversed = frames.Select(f => (f.Id,f.Frame is null?null:f.Frame with{XDirection=new(-f.Frame.XDirection.X,-f.Frame.XDirection.Y,-f.Frame.XDirection.Z)})).ToArray();
Check(Has(context,"SOURCE_MODEL_DIRECTION_MISMATCH",reversed),"opposite ray rejected without absolute-dot loophole");
Vector3 Rotate(Vector3 p)=>new(p.Z,p.X,p.Y);
var rotated = frames.Select(f => (f.Id,f.Frame is null?null:f.Frame with{XDirection=Rotate(f.Frame.XDirection),Normal=Rotate(f.Frame.Normal),OriginMm=Rotate(f.Frame.OriginMm)})).ToArray();
Check(Validate(context with{ModelOrientation=orientation with{FrontRight=Rotate(orientation.FrontRight),FrontUp=Rotate(orientation.FrontUp)}},rotated).Count==0,"proper global rotation is accepted");
Check(Validate(context with{Projection=DrawingProjection.ThirdAngle}).Count==0,"projection layout does not reverse top-view basis");
Check(Has(context with{ModelOrientation=orientation with{DirectionBindings=orientation.DirectionBindings.Select(b=>b with{UseEndRay=false}).ToArray()}},"SOURCE_MODEL_DIRECTION_MISMATCH"),"wrong reference ray rejected");
var compiled = new GenericPlanCompiler().Compile(draft,Path.GetFullPath(args[2]));
Check(compiled.Success,"full corrected compilation passes");
var plan = compiled.Plan!;
Check(!DrawingPlanValidation.ValidateCompiled(plan).Any(d=>d.Severity==DiagnosticSeverity.Error),"compiled valid plan passes");
var changed = plan with{Operations=plan.Operations.Select(o=>o is ProfileSketchOperation s && s.Id=="midS"?s with{Frame=s.Frame! with{XDirection=new(s.Frame!.XDirection.X,0,-s.Frame.XDirection.Z)}}:o).ToArray()};
changed=changed with{DrawingBindingDigest=DrawingPlanValidation.Digest(changed)};
Check(DrawingPlanValidation.ValidateCompiled(changed).Any(d=>d.Code=="SOURCE_MODEL_DIRECTION_MISMATCH"),"compiled mirror rejected even after digest recomputation");
File.WriteAllText(args[1],JsonSerializer.Serialize(new{success=true,checks=results,scope="source ray and sketch-axis correspondence; no whole-shape equivalence claim"},ModelingIrJson.Options));
